const { execSync } = require('child_process');
try {
    const r = execSync(`sqlite3 -json '/Users/redinside/.openclaw/workspace/data/social-monitoring.db' "SELECT workflow_name, COUNT(*) as failures FROM workflow_runs WHERE status='failure' AND started_at > datetime('now','-1 hour') GROUP BY workflow_name"`, {encoding:'utf8',timeout:5000}).trim();
    return [{ json: { failures: r ? JSON.parse(r) : [] } }];
} catch(e) { return [{ json: { failures: [] } }]; }

