parameters.functionCode:
// Mark DLQ items for replay
const items = $input.all();
const replayed = [];

for (const item of items) {
  replayed.push({
    json: {
      dlq_id: item.json.id,
      workflow_name: item.json.workflow_name,
      payload: item.json.payload_json,
      replay_status: 'pending'
    }
  });
}

return replayed;

